def find_connected_regions(grid_val, direction='horizontal'):
    visited = set()
    regions = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid_val[r][c] != 0 and (r,c) not in visited:
                region = []
                if direction == 'horizontal':
                    for i in range(c, len(grid[0])):
                        if grid_val[r][i] != 0:
                            region.append((r, i))
                            visited.add((r, i))
                        elif region:
                            break
                elif direction == 'vertical':
                    for i in range(r, len(grid)):
                        if grid_val[i][c] != 0:
                            region.append((i, c))
                            visited.add((i, c))
                        elif region:
                            break
                if region:
                    regions.append(region)
    return regions

